//! The XTGETTCAP tables the terminal answers from, each generated from a
//! terminfo entry: vtium's, `install/xterm-vtium.ti`, and the C
//! reference's, `install/kmscon.ti`.
//!
//! The tables are compiled in: `table.rs` is generated by the test
//! `table_matches_the_entry`, which fails when the committed tables differ
//! from the entries (`VTIUM_BLESS=1` rewrites it), as the C reference's
//! `termcap_drift` did. Each string is as ncurses' `tigetstr` gives it:
//! escapes decoded to their bytes, `%` sequences and padding as written; a
//! number is its decimal text, and a boolean has no value.
//!
//! Beside its entry's capabilities each table carries the names xterm's
//! XTGETTCAP answers that are no terminfo capability: `TN` and `name`, the
//! entry's name, and `Co`, termcap's `colors`. `cols` and `lines` are left
//! out: they give a default size, and a program asking the terminal wants
//! the real one, which `TIOCGWINSZ` reports.
//!
//! There are two tables, one for each entry vtium answers under. Under
//! `xterm-vtium`, [`NAME`], vtium answers from its own entry's table.
//! Under `kmscon`, [`KMSCON`], it answers from the C reference's, generated
//! from `install/kmscon.ti`, as the C reference answered from its table
//! while its session's `TERM` was its own entry's name
//! (`src/terminal_vte.c:36-56` at kmscon origin/main). Under any other
//! `TERM` the session finds an entry neither table describes, and every
//! name is unknown.

#[cfg(test)]
mod effects;
mod table;
#[cfg(test)]
mod terminfo;

use vtium_term::{Termcap, TermcapError};

/// The name of vtium's terminfo entry, the default `TERM`.
pub const NAME: &str = "xterm-vtium";

/// The name of the C reference's terminfo entry.
pub const KMSCON: &str = "kmscon";

/// A table: each capability's name with its value, none for a boolean,
/// sorted by name.
pub type Entries = &'static [(&'static str, Option<&'static [u8]>)];

/// The table for a session whose `TERM` is `term`; none under a name whose
/// entry vtium has no table for.
pub fn entries(term: &str) -> Option<Entries> {
    match term {
        NAME => Some(table::XTERM_VTIUM),
        KMSCON => Some(table::KMSCON),
        _ => None,
    }
}

/// [`entries`] for `term`, for [`vtium_term::Terminal::set_termcap`].
pub fn for_term(term: &str) -> Option<Result<Termcap, TermcapError>> {
    entries(term)
        .map(|table| Termcap::new(table.iter().map(|(name, value)| (name.as_bytes(), *value))))
}
